1	using System.Runtime.InteropServices;
2	using System.ComponentModel;
3	using System.Diagnostics;
4	using Microsoft.Win32;
5	
6	namespace AltHenkan;
7	
8	internal sealed partial class AltInputService : IDisposable
9	{
10	    private const nuint OwnInputMarker = 0x414C5448;
11	
12	    private readonly NativeMethods.HookProc _keyboardCallback;
13	    private readonly NativeMethods.HookProc _nextKeyboardHook;
14	    private readonly NativeMethods.HookProc _mouseCallback;
15	    private readonly HashSet<uint> _nonAltKeysDown = [];
16	    private readonly AltState _leftAlt = new(AltSide.Left);
17	    private readonly AltState _rightAlt = new(AltSide.Right);
18	    private readonly DeferredControlState _leftControl = new(ModifierSides.Left);
19	    private readonly DeferredControlState _rightControl = new(ModifierSides.Right);
20	    private readonly EmacsKeyboardState _emacsState = new();
21	    private readonly bool _initialNativeCapsLockOn;
22	    private readonly DedicatedMessageLoop? _hookThread;
23	    private readonly InputPlatform _platform;
24	    private System.Windows.Forms.Timer? _maintenanceTimer;
25	    private nint _keyboardHook;
26	    private nint _mouseHook;
27	    private AppSettings _settings;
28	    private volatile bool _disposed;
29	    private bool _refreshRequested;
30	    private long _lastRefreshAtMilliseconds;
31	    private int _hookGeneration;
32	    private long _keyboardCallbackCount;
33	    private long _mouseCallbackCount;
34	    private long _suppressedKeyboardEventCount;
35	    private long _inputInjectionFailures;
36	    private long _lastStatusAtMilliseconds;
37	    private long _imeWidthCommandEvents;
38	    private int _inputInjectionDepth;
39	    private long _inputInjectionCalls;
40	    private int _maxInputInjectionDepth;
41	    private long _keyboardCallbacksDuringInjection;
42	    private long _altReconcileChecks;
43	    private long _altReconcileInjectionSkips;
44	    private long _altReconcileInjectionSkipsWithAlt;
45	    private int _maxAltReconcileInjectionDepth;
46	    private long _altStateRecoveries;
47	
48	    public event Action<int>? InputInjectionFailed;
49	    public event Action<bool>? EmacsModeChanged;
50	
51	    public AltInputService(AppSettings settings) : this(settings, new InputPlatform())
52	    {
53	        _initialNativeCapsLockOn = (NativeMethods.GetKeyState((int)NativeMethods.VkCapsLock) & 1) != 0;
54	        _hookThread = new DedicatedMessageLoop(InitializeHookThread, CleanupHookThread);
55	        SystemEvents.PowerModeChanged += OnPowerModeChanged;
56	        SystemEvents.SessionSwitch += OnSessionSwitch;
57	    }
58	
59	    internal AltInputService(AppSettings settings, InputPlatform platform)
60	    {
61	        _platform = platform;
62	        _settings = settings.Normalize();
63	        _emacsState.SetActive(_settings.InitialEmacsActive);
64	        _keyboardCallback = KeyboardHookCallback;
65	        _nextKeyboardHook = (code, wParam, lParam) =>
66	            _platform.NextKeyboard(_keyboardHook, code, wParam, lParam);
67	        _mouseCallback = MouseHookCallback;
68	    }
69	
70	    private void InitializeHookThread()
71	    {
72	        DiagnosticLog.Write($"Dedicated hook thread started: managed thread {Environment.CurrentManagedThreadId}.");
73	        DiagnosticLog.Write($"Initial keyboard mode: {(_emacsState.Active ? "Emacs" : "Normal")}.");
74	        RegisterHooks();
75	        _lastStatusAtMilliseconds = Environment.TickCount64;
76	        WriteHookStatus("startup");
77	        TraceSettings(after: true);
78	        EnsureNativeCapsLockOff(_initialNativeCapsLockOn);
79	        _maintenanceTimer = new System.Windows.Forms.Timer { Interval = 1000 };
80	        _maintenanceTimer.Tick += (_, _) => MaintainHooks();
81	        _maintenanceTimer.Start();
82	    }
83	
84	    private void RegisterHooks()
85	    {
86	        var module = NativeMethods.GetModuleHandle(null);
87	        var keyboardHook = NativeMethods.SetWindowsHookEx(
88	            NativeMethods.WhKeyboardLl,
89	            _keyboardCallback,
90	            module,
91	            0);
92	        if (keyboardHook == 0)
93	        {
94	            throw new Win32Exception(Marshal.GetLastWin32Error(), "キーボードフックを登録できませんでした。");
95	        }
96	
97	        var mouseHook = NativeMethods.SetWindowsHookEx(
98	            NativeMethods.WhMouseLl,
99	            _mouseCallback,
100	            module,
101	            0);
102	        if (mouseHook == 0)
103	        {
104	            var errorCode = Marshal.GetLastWin32Error();
105	            NativeMethods.UnhookWindowsHookEx(keyboardHook);
106	            throw new Win32Exception(errorCode, "マウスフックを登録できませんでした。");
107	        }
108	
109	        // Install replacements first: a failed renewal must not discard a working pair.
110	        UnregisterHooks();
111	        _keyboardHook = keyboardHook;
112	        _mouseHook = mouseHook;
113	        _lastRefreshAtMilliseconds = Environment.TickCount64;
114	        _refreshRequested = false;
115	        _hookGeneration++;
116	        Trace(new() { Kind = InputTraceKind.Boundary, Reason = InputTraceReason.Registered, Index = _hookGeneration });
117	        DiagnosticLog.Write(
118	            $"Hooks registered: generation={_hookGeneration}, keyboard=0x{_keyboardHook:X}, mouse=0x{_mouseHook:X}, keyboard callbacks={_keyboardCallbackCount}, mouse callbacks={_mouseCallbackCount}.");
119	    }
120	
121	    public void UpdateSettings(AppSettings settings)
122	    {
123	        var normalized = settings.Normalize();
