        var emacsEnabled = _settings.Enabled && _settings.EmacsEnabled;
        if (data.VirtualKeyCode == NativeMethods.VkCapsLock &&
            _emacsState.HandleCapsLock(isKeyDown, emacsEnabled, out var modeChanged))
        {
            ConsumePendingAltGestures();
            if (modeChanged)
