1	using AltHenkan;
2	using System.Reflection;
3	using System.Runtime.InteropServices;
4	
5	internal static class ModifierReleaseTests
6	{
7	    private const BindingFlags Private = BindingFlags.Instance | BindingFlags.NonPublic;
8	    private static readonly uint[] Modifiers =
9	        [NativeMethods.VkLControl, NativeMethods.VkRControl, NativeMethods.VkLMenu, NativeMethods.VkRMenu];
10	    private static readonly string[] StateFields = ["_leftControl", "_rightControl", "_leftAlt", "_rightAlt"];
11	
12	    public static void Run(Action<string, bool> check)
13	    {
14	        var directory = Path.Combine(Path.GetTempPath(), "AltHenkan-Release-" + Guid.NewGuid().ToString("N"));
15	        Directory.CreateDirectory(directory);
16	        var path = Path.Combine(directory, "diagnostics.log");
17	        try
18	        {
19	            DiagnosticLog.Initialize(path: path);
20	            RunSequences(check);
21	            RunReentry(check);
22	            DiagnosticLog.Shutdown();
23	            check("Normal modifier sequences and reentry produce no residual diagnostics",
24	                !File.ReadAllText(path).Contains("Modifier release residual:") &&
25	                !File.ReadAllText(path + ".input").Contains("reason=ModifierReleaseResidual"));
26	
27	            // Both trace-enabled and trace-disabled paths must detect an actual residual.
28	            foreach (var traceEnabled in new[] { true, false })
29	            {
30	                var faultPath = Path.Combine(directory, $"fault-{traceEnabled}.log");
31	                DiagnosticLog.Initialize(path: faultPath);
32	                if (!traceEnabled) InputTrace.Shutdown();
33	                foreach (var key in Modifiers) RunFailedRelease(key, check);
34	                DiagnosticLog.Shutdown();
35	                var faults = File.ReadAllLines(faultPath).Where(l => l.Contains("Modifier release residual:")).ToArray();
36	                check($"Trace={traceEnabled}: repeated ups are deduplicated and a recovered gesture rearms reporting", faults.Length == 8);
37	                check($"Trace={traceEnabled}: fault reports identify the remaining sent-down state",
38	                    faults.All(l => l.Contains("residual=0x4")) &&
39	                    new[] { "LeftControl", "RightControl", "LeftAlt", "RightAlt" }.All(k => faults.Count(l => l.Contains($"key={k},")) == 2));
40	                if (traceEnabled)
41	                {
42	                    var trace = File.ReadAllLines(faultPath + ".input");
43	                    var residuals = trace.Where(l => l.Contains("reason=ModifierReleaseResidual")).ToArray();
44	                    check("Residual trace contains modifier identity, remaining flags and release metadata",
45	                        residuals.Length == 8 && residuals.All(l => l.Contains("residual=0x4 up=True") && l.Contains("eventTime=123")));
46	                    check("Each residual can be joined to its received key-up and exception fallback",
47	                        residuals.All(l =>
48	                        {
49	                            var obs = l.Split(' ').Single(p => p.StartsWith("obs="));
50	                            return trace.Any(e => e.Contains("kind=KeyBegin") && e.Contains("up=True") && e.Split(' ').Contains(obs)) &&
51	                                trace.Any(e => e.Contains("kind=Fallback") && e.Split(' ').Contains(obs));
52	                        }));
53	                }
54	            }
55	            RunHealthyAuditCost(check);
56	        }
57	        finally
58	        {
59	            DiagnosticLog.Shutdown();
60	            Directory.Delete(directory, true);
61	        }
62	    }
63	
64	    private static void RunSequences(Action<string, bool> check)
65	    {
66	        // PowerToys #46693/#46672 inspired sequences, independently implemented
67	        // for this app's Ctrl+F binding. Fake input is not a Windows/AltGr repro.
68	        foreach (var ctrl in Modifiers.Take(2))
69	        foreach (var alt in Modifiers.Skip(2))
70	        foreach (var emacs in new[] { true, false })
71	        foreach (var ctrlFirst in new[] { true, false })
72	        foreach (var cycles in new[] { 1, 3 })
73	        foreach (var extra in new[] { true, false })
74	        {
75	            var platform = new Platform();
76	            using var service = Create(platform, emacs);
77	            var label = $"Ctrl={ctrl:X} Alt={alt:X} Emacs={emacs} CtrlUpFirst={ctrlFirst} cycles={cycles} extra={extra}";
78	            for (var cycle = 0; cycle < cycles; cycle++)
79	            {
80	                platform.Deliver(ctrl, false);
81	                platform.Deliver(alt, false);
82	                platform.Deliver(ctrlFirst ? ctrl : alt, true);
83	                platform.Deliver(ctrlFirst ? alt : ctrl, true);
84	            }
85	            check($"{label}: modifier prelude leaves no internal or simulated OS state", Clear(service) && platform.AllUp);
86	            platform.Sent.Clear();
87	            platform.Deliver(ctrl, false);
88	            platform.Deliver((uint)Keys.F, false);
89	            if (extra) platform.Deliver((uint)Keys.X, false);
90	            platform.Deliver(ctrlFirst ? ctrl : (uint)Keys.F, true);
91	            platform.Deliver(ctrlFirst ? (uint)Keys.F : ctrl, true);
92	            if (extra) platform.Deliver((uint)Keys.X, true);
93	            check($"{label}: subsequent shortcut emits the configured action only when enabled",
94	                platform.Sent.Contains(((uint)Keys.Right, false)) == emacs &&
95	                platform.Sent.Contains(((uint)Keys.Right, true)) == emacs);
96	            check($"{label}: shortcut and all modifiers finish released", Clear(service) && platform.AllUp);
97	            var sentBefore = platform.Sent.Count;
98	            check($"{label}: following ordinary input passes without a stale modifier",
99	                platform.Deliver((uint)Keys.A, false) == 0 && platform.Deliver((uint)Keys.A, true) == 0 &&
100	                platform.Sent.Count == sentBefore && platform.AllUp);
101	        }
102	    }
103	
104	    private static void RunReentry(Action<string, bool> check)
105	    {
106	        foreach (var key in Modifiers)
107	        {
108	            var platform = new Platform();
109	            using var service = Create(platform, false);
110	            // With Emacs disabled Ctrl passes directly; an ordinary held key
111	            // similarly makes Alt pass. Reenter forwarding of the release with
112	            // a new down: this is fault injection, not an observed OS ordering.
113	            platform.Deliver((uint)Keys.X, false);
114	            platform.Deliver(key, false);
115	            platform.OnForward = () => platform.Deliver(key, false);
116	            platform.Deliver(key, true);
117	            check($"{key:X}: new down during release remains tracked", StateFlag(service, key, "IsDown"));
118	            platform.Deliver(key, true);
119	            platform.Deliver((uint)Keys.X, true);
120	            check($"{key:X}: reentrant new gesture can subsequently release", Clear(service) && platform.AllUp);
121	        }
122	    }
123	
124	    private static void RunFailedRelease(uint key, Action<string, bool> check)
125	    {
126	        var platform = new Platform();
127	        using var service = Create(platform, true);
128	        for (var episode = 0; episode < 2; episode++)
129	        {
130	            platform.Deliver(key, false);
131	            platform.Deliver((uint)Keys.X, false); // Promote the deferred modifier.
132	            platform.Deliver((uint)Keys.X, true);
133	            check($"{key:X}: fault setup has a sent modifier", StateFlag(service, key, "NativeDownSent"));
134	            platform.FailSend = true;
135	            platform.Deliver(key, true); // Throws before the handler can reset its flags.
136	            check($"{key:X}: diagnostic observes but does not repair the injected residual",
137	                !StateFlag(service, key, "IsDown") && StateFlag(service, key, "NativeDownSent"));
138	            for (var i = 0; i < 3; i++) platform.Deliver(key, true);
139	            // A new complete gesture clears the residual and rearms the diagnostic.
140	            platform.Deliver(key, false);
141	            platform.Deliver(key, true);
142	            check($"{key:X}: normal next gesture clears the fault state", Clear(service) && platform.AllUp);
143	        }
144	    }
145	
146	    private static void RunHealthyAuditCost(Action<string, bool> check)
147	    {
148	        // Compare actual handlers directly, excluding the existing hook struct
149	        // marshalling allocation from the cost of this added diagnostic.
150	        var platform = new Platform();
151	        using var service = Create(platform, false);
152	        foreach (var field in StateFields)
153	        {
154	            var state = typeof(AltInputService).GetField(field, Private)!.GetValue(service)!;
155	            typeof(ModifierReleaseTests).GetMethod(nameof(MeasureHealthyAudit), BindingFlags.Static | BindingFlags.NonPublic)!
156	                .MakeGenericMethod(state.GetType()).Invoke(null, [service, state, platform, check, field]);
157	        }
158	    }
159	
160	    private delegate nint ModifierHandler<T>(T state, int code, nint message, nint pointer,
161	        NativeMethods.KbdLlHookStruct data, bool down);
162	
163	    private static void MeasureHealthyAudit<T>(AltInputService service, T state, Platform platform,
164	        Action<string, bool> check, string label)
165	    {
