5	internal static class AltRecoveryTests
6	{
7	    public static void RunNative(AltInputService service, DedicatedMessageLoop loop, Action<string, bool> check)
8	    {
9	        loop.InvokeAsync(() =>
10	        {
11	            var flags = BindingFlags.Instance | BindingFlags.NonPublic;
12	            var type = typeof(AltInputService);
13	            var reconcile = type.GetMethod("ReconcileReleasedAlt", flags)!;
14	            long Counter(string name) => (long)type.GetField(name, flags)!.GetValue(service)!;
15	            var checkAll = type.GetMethod("ReconcileReleasedAlts", flags)!;
16	            foreach (var side in new[] { "_leftAlt", "_rightAlt" })
17	            {
18	                var state = type.GetField(side, flags)!.GetValue(service)!;
19	                var stateType = state.GetType();
20	                void Set(string property, object value) => stateType.GetProperty(property)!.SetValue(state, value);
21	                bool Get(string property) => (bool)stateType.GetProperty(property)!.GetValue(state)!;
22	                void Reset() => stateType.GetMethod("Reset")!.Invoke(state, null);
23	                void Observe(bool reliable, bool down, long now) =>
24	                    reconcile.Invoke(service, [state, reliable, (nint)1, down, now]);
25	                try
26	                {
27	                    stateType.GetMethod("Start")!.Invoke(state, [(uint)0x38, side == "_rightAlt"]);
28	                    Set("NativeDownSent", true);
29	                    Observe(true, false, 1000);
30	                    check($"Native {side} state survives first release sample", Get("IsDown"));
31	                    Observe(true, false, 2000);
32	                    check($"Native {side} stale state is reset on the actual service", !Get("IsDown") && !Get("NativeDownSent"));
33	                    check("Actual service requests idle hook renewal after Alt reconciliation",
34	                        (bool)type.GetField("_refreshRequested", flags)!.GetValue(service)!);
35	
36	                    stateType.GetMethod("Start")!.Invoke(state, [(uint)0x38, side == "_rightAlt"]);
37	                    Observe(true, false, 1000);
38	                    Observe(true, false, 2000);
39	                    check($"Native {side} hidden long-press state is preserved", Get("IsDown"));
40	                    Set("OriginalDownPassed", true);
41	                    Observe(true, true, 3000);
42	                    Observe(true, true, 4000);
43	                    check($"Native {side} held forwarded Alt is preserved", Get("IsDown"));
44	                    Observe(false, false, 5000);
45	                    Observe(false, false, 6000);
46	                    check($"Native {side} does not recover from inaccessible samples", Get("IsDown"));
47	                    Observe(true, false, 7000);
48	                    var checksBefore = Counter("_altReconcileChecks");
49	                    var skipsBefore = Counter("_altReconcileInjectionSkips");
50	                    var altSkipsBefore = Counter("_altReconcileInjectionSkipsWithAlt");
51	                    type.GetField("_inputInjectionDepth", flags)!.SetValue(service, 1);
52	                    checkAll.Invoke(service, null);
53	                    type.GetField("_inputInjectionDepth", flags)!.SetValue(service, 0);
54	                    check("Artificial in-flight sample counts one check and one Alt-held exclusion",
55	                        Counter("_altReconcileChecks") == checksBefore + 1 &&
56	                        Counter("_altReconcileInjectionSkips") == skipsBefore + 1 &&
57	                        Counter("_altReconcileInjectionSkipsWithAlt") == altSkipsBefore + 1);
58	                    Observe(true, false, 8000);
59	                    check("In-flight SendInput invalidates release confirmation", Get("IsDown"));
60	                    Observe(true, false, 9000);
61	                    check("Forwarded Alt recovers after fresh reliable observations", !Get("IsDown"));
62	                }
63	                finally
64	                {
65	                    // Never let a synthetic test state reach Dispose's real key-up sender.
66	                    Reset();
67	                    type.GetField("_inputInjectionDepth", flags)!.SetValue(service, 0);
68	                }
69	            }
70	            var checks = Counter("_altReconcileChecks");
71	            var skips = Counter("_altReconcileInjectionSkips");
72	            var altSkips = Counter("_altReconcileInjectionSkipsWithAlt");
73	            checkAll.Invoke(service, null);
74	            check("Idle check counts a call without a false injection exclusion",
75	                Counter("_altReconcileChecks") == checks + 1 &&
76	                Counter("_altReconcileInjectionSkips") == skips);
77	            try
78	            {
79	                // Artificial depth verifies instrumentation, not real Windows reentrancy.
80	                type.GetField("_inputInjectionDepth", flags)!.SetValue(service, 2);
81	                checkAll.Invoke(service, null);
82	                check("In-flight check without Alt is distinguished from Alt-held exclusion",
83	                    Counter("_altReconcileInjectionSkips") == skips + 1 &&
84	                    Counter("_altReconcileInjectionSkipsWithAlt") == altSkips &&
85	                    (int)type.GetField("_maxAltReconcileInjectionDepth", flags)!.GetValue(service)! == 2);
86	            }
87	            finally { type.GetField("_inputInjectionDepth", flags)!.SetValue(service, 0); }
88	            var calls = Counter("_inputInjectionCalls");
89	            // An empty batch exercises the real wrapper without sending a keyboard event.
90	            type.GetMethod("SendKeyboardInputs", flags)!.Invoke(service, [Array.Empty<NativeMethods.Input>()]);
91	            check("Input wrapper counts calls, records depth, and restores depth on return",
92	                Counter("_inputInjectionCalls") == calls + 1 &&
93	                (int)type.GetField("_maxInputInjectionDepth", flags)!.GetValue(service)! >= 1 &&
94	                (int)type.GetField("_inputInjectionDepth", flags)!.GetValue(service)! == 0);
95	            checkAll.Invoke(service, null);
96	            check("Completed input wrapper does not produce another exclusion",
97	                Counter("_altReconcileInjectionSkips") == skips + 1);
98	            var reliable = AsyncKeyStateAccess.TryReadAlt(out _, out _, out _);
99	            Console.WriteLine($"Native Alt state access guard: reliable={reliable}.");
100	        }).WaitAsync(TimeSpan.FromSeconds(5)).GetAwaiter().GetResult();
101	    }
