103	    public static void Run(Action<string, bool> check)
104	    {
105	        RunAltRepress(check);
106	        // Match 2026-10-11: tracked left Alt and NativeDownSent, but async Alt is up.
107	        var stale = new AltModifierSnapshot(true, false, true, false);
108	        check("Released native Alt is not used as an Emacs modifier", !stale.Active);
109	        check("Released native Alt is not restored after Emacs input", !stale.ShouldRestore);
